'use client';
import { ReactNode } from 'react';
import { motion, MotionConfig, useReducedMotion, Variants } from 'motion/react';
import { motionElementOf } from './motion-elements';
import React from 'react';

export type PresetType =
  | 'fade'
  | 'slide'
  | 'scale'
  | 'blur'
  | 'blur-slide'
  | 'zoom'
  | 'flip'
  | 'bounce'
  | 'rotate'
  | 'swing';

export type AnimatedGroupProps = {
  children: ReactNode;
  className?: string;
  variants?: {
    container?: Variants;
    item?: Variants;
  };
  preset?: PresetType;
  as?: React.ElementType;
  asChild?: React.ElementType;
};

const defaultContainerVariants: Variants = {
  visible: {
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const defaultItemVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

const presetVariants: Record<PresetType, Variants> = {
  fade: {},
  slide: {
    hidden: { y: 20 },
    visible: { y: 0 },
  },
  scale: {
    hidden: { scale: 0.8 },
    visible: { scale: 1 },
  },
  blur: {
    hidden: { filter: 'blur(4px)' },
    visible: { filter: 'blur(0px)' },
  },
  'blur-slide': {
    hidden: { filter: 'blur(4px)', y: 20 },
    visible: { filter: 'blur(0px)', y: 0 },
  },
  zoom: {
    hidden: { scale: 0.5 },
    visible: {
      scale: 1,
      transition: { type: 'spring', stiffness: 300, damping: 20 },
    },
  },
  flip: {
    hidden: { rotateX: -90 },
    visible: {
      rotateX: 0,
      transition: { type: 'spring', stiffness: 300, damping: 20 },
    },
  },
  bounce: {
    hidden: { y: -50 },
    visible: {
      y: 0,
      transition: { type: 'spring', stiffness: 400, damping: 10 },
    },
  },
  rotate: {
    hidden: { rotate: -180 },
    visible: {
      rotate: 0,
      transition: { type: 'spring', stiffness: 200, damping: 15 },
    },
  },
  swing: {
    hidden: { rotate: -10 },
    visible: {
      rotate: 0,
      transition: { type: 'spring', stiffness: 300, damping: 8 },
    },
  },
};

const addDefaultVariants = (variants: Variants) => ({
  hidden: { ...defaultItemVariants.hidden, ...variants.hidden },
  visible: { ...defaultItemVariants.visible, ...variants.visible },
});

function ReducedMotionConfig({ children }: { children: ReactNode }) {
  const prefersReducedMotion = useReducedMotion();
  if (!prefersReducedMotion) {
    return children;
  }
  return <MotionConfig reducedMotion='always'>{children}</MotionConfig>;
}

function AnimatedGroup({
  children,
  className,
  variants,
  preset,
  as = 'div',
  asChild = 'div',
}: AnimatedGroupProps) {
  const selectedVariants = {
    item: addDefaultVariants(preset ? presetVariants[preset] : {}),
    container: addDefaultVariants(defaultContainerVariants),
  };
  const containerVariants = variants?.container || selectedVariants.container;
  const itemVariants = variants?.item || selectedVariants.item;

  const MotionComponent = motionElementOf(as) as typeof motion.div;
  const MotionChild = motionElementOf(asChild) as typeof motion.div;

  return (
    <ReducedMotionConfig>
      <MotionComponent
        initial='hidden'
        animate='visible'
        variants={containerVariants}
        className={className}
      >
        {React.Children.map(children, (child, index) => (
          <MotionChild key={index} variants={itemVariants}>
            {child}
          </MotionChild>
        ))}
      </MotionComponent>
    </ReducedMotionConfig>
  );
}

export { AnimatedGroup };

import { motion } from 'motion/react';

const MOTION_ELEMENTS = {
  a: motion.a,
  article: motion.article,
  aside: motion.aside,
  blockquote: motion.blockquote,
  button: motion.button,
  code: motion.code,
  div: motion.div,
  em: motion.em,
  figure: motion.figure,
  footer: motion.footer,
  h1: motion.h1,
  h2: motion.h2,
  h3: motion.h3,
  h4: motion.h4,
  h5: motion.h5,
  h6: motion.h6,
  header: motion.header,
  label: motion.label,
  li: motion.li,
  main: motion.main,
  nav: motion.nav,
  ol: motion.ol,
  p: motion.p,
  pre: motion.pre,
  section: motion.section,
  small: motion.small,
  span: motion.span,
  strong: motion.strong,
  ul: motion.ul,
};

type MotionElementTag = keyof typeof MOTION_ELEMENTS;

function isMotionElementTag(tag: unknown): tag is MotionElementTag {
  const isString = typeof tag === 'string';
  return isString && tag in MOTION_ELEMENTS;
}

/**
 * The motion version of an HTML tag. A lookup such as `motion[tag]` is invisible to the bundler,
 * which drops the tags it never sees and breaks the production build, so every tag is listed here.
 */
export function motionElementOf(tag: unknown) {
  if (isMotionElementTag(tag)) {
    return MOTION_ELEMENTS[tag];
  }
  return MOTION_ELEMENTS.div;
}
